function renderProductForm(s) {
  const optionGroup=(name,type,min,max,choices)=>`<div class="option-group"><div class="option-group-head"><strong>${name}</strong><span class="pill ${type==='Obligatoire'?'pill-red':'pill-success'}">${type}</span></div><div class="option-rule-row"><span>Minimum <strong>${min}</strong></span><span>Maximum <strong>${max}</strong></span><small>${choices.length} options disponibles</small></div>${choices.map(([label,price])=>`<div class="option-choice"><span>${label}</span><span>+ ${price} FCFA</span></div>`).join('')}</div>`;
  return `<div class="form-layout"><section class="stack"><article class="panel"><div class="panel-title"><h2>Informations du produit</h2><span class="subtle">Simple ou personnalisable</span></div><div class="field-grid"><div class="field"><label>Nom du produit</label><input value="Poulet braisé · exemple"></div><div class="field"><label>Prix de base</label><input value="3 500 FCFA"></div><div class="field full"><label>Description</label><textarea placeholder="Décrivez le produit…"></textarea></div><div class="field"><label>Catégorie</label><select><option>Plats · démo</option></select></div><div class="field"><label>Disponibilité commerciale</label><select><option>Publié · disponible</option><option>Désactivé</option><option>Marqué indisponible / épuisé</option><option>Réactivé</option></select></div></div><div class="availability-control"><div><strong>Disponibilité indépendante du stock</strong><small>Publier, désactiver, marquer indisponible ou réactiver ce produit.</small></div><span class="pill pill-success">Publié · disponible</span></div></article><article class="panel"><div class="panel-title"><h2>Suivi du stock · facultatif</h2><span class="pill pill-success">Réglage par produit</span></div><div class="toggle-line"><span class="toggle on"></span><span class="toggle-copy"><strong>Activer le suivi du stock</strong><small>Le suivi est activé uniquement pour ce produit.</small></span></div><div class="field"><label>Quantité disponible</label><input value="12" inputmode="numeric"><small class="field-hint">À zéro, le produit n’est plus commandable. Le serveur bloque une quantité supérieure au stock.</small></div><div class="banner-notice"><span class="notice-icon">i</span><span>Si le suivi est désactivé, le commerçant reste responsable de la disponibilité manuelle. Un article indisponible est toujours refusé.</span></div></article><article class="panel"><div class="panel-title"><h2>Options et suppléments</h2><span class="subtle">Aucune option ou plusieurs groupes</span></div><p class="subtle">Chaque groupe est facultatif ou obligatoire et définit le minimum et le maximum de choix.</p>${optionGroup('Cuisson','Obligatoire',1,1,[['À point',0],['Bien cuit',0]])}${optionGroup('Accompagnement','Facultatif',0,1,[['Riz',0],['Frites',500],['Salade',300]])}${optionGroup('Suppléments','Facultatif',0,2,[['Fromage',400],['Sauce maison',200]])}<button class="btn btn-outline btn-small" style="margin-top:10px">＋ Ajouter un groupe</button><div class="footer-note">Un groupe obligatoire impose au moins 1 choix ; un groupe facultatif peut en autoriser 0. Le maximum ne dépasse pas le nombre d’options du groupe.</div></article><div class="form-actions"><span class="subtle">Exemple de conception uniquement</span>${btn('Enregistrer le produit')}</div></section><aside class="stack"><article class="side-help"><h3>Optionnel par produit</h3><p>Le produit peut être vendu sans options. Chaque choix peut ajouter un supplément de prix, qui sera recalculé côté serveur.</p></article><article class="panel"><div class="panel-title"><h3>Contrôles côté serveur</h3></div><div class="pay-step"><span class="step-num">1</span><span>Disponibilité et quantités, selon le suivi activé.</span></div><div class="pay-step"><span class="step-num">2</span><span>Minima, maxima, nombre d’options et prix.</span></div><div class="pay-step"><span class="step-num">3</span><span>Copie des options et suppléments tarifés dans la ligne de commande.</span></div></article></aside></div>`;
}

function renderReservationCard(role) {
  const isClient=role==='Client', isAdmin=role==='Administration';
  const permissions=isAdmin?'L’administrateur peut libérer les réservations actives de tous les commerçants.':'Vous ne pouvez libérer que les réservations des commandes de votre commerce.';
  const action=isAdmin?'Libérer une réservation active':'Libérer la réservation active';
  return `<article class="panel reservation-card"><div class="panel-title"><div><h2>Réservation de stock · exemple distinct</h2><div class="panel-sub">Autre commande de démonstration · #DF-24011</div></div><span class="pill pill-warn">active · non consommée</span></div><div class="reservation-grid"><div class="reservation-metric"><small>Quantité réservée</small><strong>Poulet braisé × 1</strong></div><div class="reservation-metric"><small>Prochaine étape</small><strong>Consommée après validation manuelle du paiement</strong></div></div><div class="reservation-summary"><strong>Sans expiration automatique</strong><span>Un refus de paiement ou une annulation avant consommation libère la réservation. Après consommation, restitution uniquement si l’annulation précède la préparation ou la remise au client ; aucune restitution automatique après ces étapes.</span></div>${isClient?`<div class="timeline-item reservation-notice"><span class="timeline-dot">i</span><div><strong>Exemple distinct de la commande en préparation ci-dessus.</strong><small>Le stock de la commande annulée suit uniquement les règles de libération ou de restitution selon son état.</small></div></div>`:`<div class="release-box"><div class="panel-title"><div><h3>${action}</h3><div class="panel-sub">${permissions}</div></div><span class="pill pill-danger">Motif requis</span></div><div class="field"><label>Motif obligatoire</label><textarea placeholder="Décrire le motif de libération"></textarea></div><div class="release-actions"><span class="field-hint">Si la commande est affectée, toute transition réelle de réservation notifie le client et le commerçant avec statut, montant concerné et action attendue.</span><button class="btn btn-outline" type="button">${action}</button></div><p class="field-hint">Une réservation consommée ne peut pas être libérée comme active. Toute libération qui laisserait la commande active dans un état incohérent doit être bloquée.</p></div>`}${isAdmin?`<div class="audit-example"><strong>Exemple de journal · autre commande de démonstration</strong><div class="audit-row"><span>06 nov. 2026 · 10:42 · Administrateur Démo</span><span>Réservation libérée avant consommation</span><span>Motif : annulation avant préparation · Quantité : 2</span></div></div>`:''}</article>`;
}

function renderChangeProposal(role) {
  if(role==='Commerçant') return `<article class="panel proposal-builder"><div class="panel-title"><div><h2>Article indisponible pendant la préparation</h2><div class="panel-sub">Proposer au client le retrait ou le remplacement de l’article</div></div><span class="pill pill-warn">pending_customer_approval</span></div><div class="proposal-choices"><div class="proposal-choice"><strong>Composition actuelle · snapshot</strong><span>Accompagnement · Frites × 1</span><small>Article signalé indisponible · exemple</small></div><div class="proposal-choice"><strong>Nouvelle composition proposée</strong><span>Remplacer par · Riz × 1</span><small>Le commerçant ne modifie pas la commande seul.</small></div></div><div class="proposal-total"><div><small>Ancien montant</small><strong>10 000 FCFA</strong></div><span>→</span><div><small>Nouveau montant proposé</small><strong>9 500 FCFA</strong></div><span class="pill pill-danger">− 500 FCFA</span></div><div class="proposal-actions"><button class="btn btn-outline" type="button">Proposer le retrait</button><button class="btn btn-primary" type="button">Envoyer la proposition au client</button></div><div class="reservation-summary"><strong>La modification exige l’accord explicite du client.</strong><span>Si le client refuse, il choisit l’annulation totale ou les seuls articles concernés ; ce périmètre est enregistré dans la demande. Si la préparation a commencé, vous confirmez son arrêt à l’ouverture de l’annulation.</span></div><div class="change-payment-rules"><div><strong>Montant en baisse après paiement</strong><span>Le commerçant rembourse directement la différence. Delifast enregistre et vérifie la preuve ; aucun transfert Mobile Money n’est exécuté par Delifast.</span></div><div><strong>Montant en hausse après paiement</strong><span>Le paiement complémentaire doit être payé et vérifié avant la poursuite de la commande.</span></div></div></article>`;
  if(role==='Client') return `<article class="panel proposal-card"><div class="panel-title"><div><h2>Proposition du commerce</h2><div class="panel-sub">Votre accord explicite est requis</div></div><span class="pill pill-warn">pending_customer_approval</span></div><div class="proposal-choices"><div class="proposal-choice"><strong>Composition actuelle · snapshot</strong><span>Frites · accompagnement</span><small>Commande #DF-24018 · composition conservée</small></div><div class="proposal-choice"><strong>Nouvelle composition proposée</strong><span>Riz · accompagnement</span><small>Retrait ou remplacement proposé par le commerce</small></div></div><div class="proposal-total"><div><small>Ancien montant</small><strong>10 000 FCFA</strong></div><span>→</span><div><small>Nouveau montant proposé</small><strong>9 500 FCFA</strong></div><span class="pill pill-danger">− 500 FCFA</span></div><div class="proposal-actions"><button class="btn btn-primary" type="button">Accepter la modification</button><button class="btn btn-outline" type="button">Refuser</button></div><div class="cancel-scope-preview"><div class="panel-title"><div><h3>Après votre refus · choix du périmètre</h3><div class="panel-sub">Aperçu de l’étape suivante ; votre choix est enregistré dans la demande d’annulation.</div></div></div><div class="proposal-choices"><div class="proposal-choice"><strong>Annulation totale</strong><span>Rembourser tout le montant payé · 10 000 FCFA</span><small>Aucun article ne reprend après finalisation.</small></div><div class="proposal-choice"><strong>Annulation partielle</strong><span>Annuler une unité ciblée · 2 700 FCFA</span><small>Prix net historique avec option, remises de ligne et part de remise globale ; les frais partagés restent inchangés.</small></div></div></div><div class="reservation-summary"><strong>Aucun changement sans votre accord explicite.</strong><span>Après le refus, les articles concernés sont suspendus. Si la préparation a commencé, le commerçant confirme son arrêt à l’ouverture de l’annulation.</span></div><div class="change-payment-rules"><div><strong>Si le montant baisse après paiement</strong><span>Le commerçant rembourse directement la différence ; Delifast enregistre et vérifie la preuve.</span></div><div><strong>Si le montant augmente après paiement</strong><span>Un paiement complémentaire doit être payé et vérifié avant la poursuite.</span></div></div></article>`;
  return '';
}

function renderCancellationWorkflow(role) {
  const isClient=role==='Client', isMerchant=role==='Commerçant', isAdmin=role==='Administration';
  const audienceNote=isClient
    ? `Le commerçant rembourse directement ; Delifast vérifie la preuve avant la finalisation. Le périmètre choisi après votre refus figure dans la demande d’annulation.`
    : isMerchant
      ? `Les articles concernés restent suspendus. Si la préparation a commencé, confirmez son arrêt à l’ouverture de l’annulation.`
      : `La preuve doit être vérifiée manuellement. En cas de rejet, un motif est transmis au commerçant et la régularisation reste en attente.`;
  const notificationExample=isClient
    ? `<div class="notification-meta"><div><small>Statut atteint · libellé</small><strong>cancellation_pending · Annulation en cours</strong></div><div><small>Montant concerné</small><strong>2 700 FCFA</strong></div><div><small>Action attendue · client</small><strong>Attendre la preuve corrigée puis sa vérification</strong></div></div>`
    : isMerchant
      ? `<div class="notification-meta"><div><small>Statut atteint · libellé</small><strong>rejected · Preuve de remboursement rejetée</strong></div><div><small>Montant concerné</small><strong>2 700 FCFA</strong></div><div><small>Action attendue · commerçant</small><strong>Corriger et renvoyer la preuve</strong></div></div>`
      : `<div class="notification-meta"><div><small>Statut atteint · libellé</small><strong>proof_submitted · Preuve de remboursement transmise</strong></div><div><small>Montant concerné</small><strong>2 700 FCFA</strong></div><div><small>Action attendue · client</small><strong>Attendre la vérification</strong></div><div><small>Action attendue · commerçant</small><strong>Attendre la décision de l’administrateur</strong></div></div>`;
  const notification=`<div class="in-app-notification notification-rules"><div class="panel-title"><div><h3>${isAdmin?'Règles de notification · aperçu statique':'Notification dans l’application · aperçu statique'}</h3><div class="panel-sub">Chaque transition réelle vers l’état indiqué déclenche le message aux deux parties.</div></div><span class="pill pill-success">Client + commerçant</span></div><div class="notification-rule-grid"><div class="notification-rule"><strong>Commande / annulation</strong><span><code>pending_payment</code> · Paiement en attente ; <code>confirmed</code> · Commande confirmée ; <code>preparing</code> · Préparation commencée ; <code>cancellation_pending</code> · Annulation en cours ; <code>partially_cancelled</code> · Annulation partielle finalisée ; <code>cancelled</code> · Commande annulée ; <code>completed</code> · Commande terminée.</span></div><div class="notification-rule"><strong>Paiement de commande · libellés existants</strong><span>À vérifier · Paiement à vérifier ; Validé · Paiement validé ; Refusé · Paiement refusé.</span></div><div class="notification-rule"><strong>Modification</strong><span><code>pending_customer_approval</code> · Réponse du client attendue ; <code>accepted</code> · Modification acceptée ; <code>rejected</code> · Modification refusée.</span></div><div class="notification-rule"><strong>Remboursement</strong><span><code>not_required</code> · Remboursement non requis ; <code>pending</code> · Remboursement attendu ; <code>proof_submitted</code> · Preuve de remboursement transmise ; <code>verified</code> · Remboursement vérifié ; <code>rejected</code> · Preuve de remboursement rejetée — correction attendue.</span></div><div class="notification-rule"><strong>Réservation affectant la commande</strong><span><code>active</code> · Réservation de stock active ; <code>consumed</code> · Réservation de stock consommée ; <code>released</code> · Réservation de stock libérée.</span></div><div class="notification-rule"><strong>Préparation · confirmations, sans nouveau statut</strong><span>Arrêt de préparation confirmé ; Reprise de préparation confirmée.</span></div></div>${notificationExample}<p>Chaque message indique le statut atteint, le montant concerné et l’action propre à son destinataire. Un brouillon ou une modification sans transition n’envoie rien. « Aucune action requise » est utilisé lorsqu’il n’y a rien à faire. Tous les états affichés sont déjà prévus ; aucun nouveau statut n’est ajouté. Notifications dans l’application uniquement : aucun SMS ni e-mail en v1. Ceci est un aperçu, aucun message réel n’est envoyé.</p></div>`;
  const merchantControls=isMerchant
    ? `<div class="scope-grid"><div class="scope-card"><strong>À l’ouverture de l’annulation</strong><span>Si la préparation a commencé, le commerçant confirme son arrêt.</span><button class="btn btn-outline" type="button">Confirmer l’arrêt de la préparation · aperçu</button></div><div class="scope-card"><strong>Après finalisation partielle</strong><span>Le commerçant confirme la reprise des articles restants.</span><button class="btn btn-primary" type="button">Confirmer la reprise des articles restants · aperçu</button></div></div><div class="reservation-summary"><strong>Annulation totale : aucune reprise.</strong><span>Les commandes entièrement annulées ne reprennent pas leur préparation.</span></div>`
    : '';
  const refundAction=isMerchant
    ? `<div class="refund-action"><div class="panel-title"><div><h3>Remboursement direct · commerçant</h3><div class="panel-sub">Exemple d’une unité annulée · prix net historique avec options et remises</div></div><span class="pill pill-warn">proof_submitted</span></div><div class="field-grid"><div class="field"><label>Montant à rembourser</label><input value="2 700 FCFA" readonly></div><div class="field"><label>Référence de transaction</label><input value="REF-DEMO-0418" readonly></div><div class="field full"><label>Preuve du remboursement</label><button class="btn btn-outline" type="button">Joindre une preuve · aperçu</button></div></div><p>Le commerçant rembourse directement au client, puis transmet la référence et la preuve. Delifast vérifie ; il ne déclenche pas le transfert. Tout dépôt ajouté reste conservé dans l’historique.</p></div>`
    : '';
  const correctedProof=isMerchant
    ? `<div class="refund-action rejected-proof"><div class="panel-title"><div><h3>Après rejet · preuve corrigée</h3><div class="panel-sub">Le rejet ne finalise pas l’annulation.</div></div><span class="pill pill-danger">rejected</span></div><p><strong>Motif transmis par l’administrateur · exemple :</strong> référence de transaction illisible ; transmettre une preuve lisible.</p><p>L’annulation reste <code>cancellation_pending</code>. Le commerçant peut renvoyer une preuve corrigée ; seul l’administrateur la vérifie. Aucun nombre maximal de renvois ni expiration automatique.</p><div class="field-grid"><div class="field"><label>Montant corrigé</label><input value="2 700 FCFA" readonly></div><div class="field"><label>Référence corrigée · aperçu</label><input value="REF-DEMO-0418-C" readonly></div><div class="field full"><label>Preuve corrigée</label><button class="btn btn-outline" type="button">Joindre la preuve corrigée</button></div></div><button class="btn btn-primary" type="button">Transmettre la preuve corrigée · aperçu</button></div>`
    : '';
  const verifyAction=isAdmin
    ? `<div class="refund-action"><div class="panel-title"><div><h3>Vérification par Delifast</h3><div class="panel-sub">Référence · REF-DEMO-0418-C · preuve corrigée de démonstration</div></div><span class="pill pill-warn">proof_submitted</span></div><div class="empty-state"><div class="empty-ico">▧</div><h3>Preuve reçue · aperçu fictif</h3><p>Seul l’administrateur vérifie la référence et la preuve avant toute décision. Le dépôt seul ne finalise pas l’annulation.</p></div><div class="field"><label>Motif obligatoire en cas de rejet</label><textarea placeholder="Indiquer au commerçant ce qui doit être corrigé · motif transmis au commerçant"></textarea></div><div class="proposal-actions"><button class="btn btn-primary" type="button">Marquer verified après vérification</button><button class="btn btn-outline" type="button">Rejeter avec un motif · aperçu</button></div><p class="field-hint">Le motif du rejet est transmis au commerçant pour correction. Aucune décision réelle n’est prise ici.</p></div><div class="refund-action rejected-proof"><div class="panel-title"><div><h3>Après renvoi d’une preuve corrigée</h3><div class="panel-sub">L’administrateur examine à nouveau le justificatif.</div></div><span class="pill pill-warn">proof_submitted</span></div><p>Le remboursement revient au parcours de vérification existant ; l’annulation n’est pas finalisée avant une vérification positive.</p><div class="proposal-actions"><button class="btn btn-primary" type="button">Vérifier à nouveau · aperçu</button><button class="btn btn-outline" type="button">Rejeter avec un motif · aperçu</button></div></div>`
    : '';
  const proofHistory=(isMerchant||isAdmin)
    ? `<div class="audit-example proof-history"><strong>Historique append-only · dépôts et décisions fictifs</strong><div class="audit-row"><strong>Dépôt 1 · proof_submitted</strong><span>Auteur : Commerçant Démo · Date : 06 nov. 2026, 11:12 · Montant : 2 700 FCFA · Référence : REF-DEMO-0418 · Preuve : preuve-1.png</span></div><div class="audit-row"><strong>Décision 1 · rejected</strong><span>Auteur : Administrateur Démo · Date : 06 nov. 2026, 11:30 · Montant : 2 700 FCFA · Référence : REF-DEMO-0418 · Preuve associée : preuve-1.png · Motif de rejet : référence illisible.</span></div><div class="audit-row"><strong>Dépôt 2 · proof_submitted</strong><span>Auteur : Commerçant Démo · Date : 06 nov. 2026, 11:45 · Montant : 2 700 FCFA · Référence : REF-DEMO-0418-C · Preuve : preuve-corrigee-2.png · En attente de vérification par l’administrateur.</span></div><p>Historique append-only : aucun dépôt ni aucune décision n’est écrasé. Aucune limite arbitraire de renvoi ni expiration automatique. Le rejet laisse l’annulation en attente ; le commerçant peut soumettre une nouvelle preuve et seul l’administrateur la vérifie.</p></div>`
    : '';
  return `<article class="panel cancellation-workflow"><div class="panel-title"><div><h2>Après un refus · annulation et remboursement</h2><div class="panel-sub">Étapes successives du registre · pas des états simultanés</div></div><span class="pill pill-warn">cancellation_pending</span></div><p class="workflow-lead">${audienceNote}</p>${notification}<div class="workflow-sequence"><div class="workflow-step"><small>Refus de la modification</small><strong><code>pending_customer_approval</code> → <code>rejected</code></strong><span>Le client choisit l’annulation totale ou les seuls articles concernés ; ce choix est enregistré dans la demande.</span></div><div class="workflow-step"><small>Avant validation du paiement</small><strong><code>pending_payment</code> → <code>cancellation_pending</code> → <code>cancelled</code></strong><span>Remboursement <code>not_required</code> ; libérer les réservations actives concernées avant finalisation.</span></div><div class="workflow-step"><small>Après paiement validé</small><strong><code>confirmed</code> ou <code>preparing</code> → <code>cancellation_pending</code></strong><span>Si la préparation a commencé, le commerçant confirme son arrêt à l’ouverture de l’annulation.</span></div></div><div class="scope-grid"><div class="scope-card"><strong>Annulation totale</strong><span>Rembourser tout le montant effectivement payé : 10 000 FCFA dans cet exemple. Après vérification positive : <code>cancelled</code>.</span><small>Aucune reprise de préparation après finalisation totale.</small></div><div class="scope-card"><strong>Annulation partielle</strong><span>Une unité du Poulet braisé : 3 000 + 500 de supplément − 500 de remise de ligne − 300 de remise globale = 2 700 FCFA.</span><small>La remise globale de 1 000 FCFA est répartie au prorata (600/400) et snapshotée. Les frais partagés de 1 000 FCFA restent inchangés. Après finalisation, le commerçant confirme la reprise du reste.</small></div></div><div class="refund-statuses"><div class="panel-title"><h3>États de remboursement</h3><span class="subtle">La preuve déposée ne finalise pas</span></div><div class="refund-state-grid"><div><code>not_required</code><span>Aucun paiement validé</span></div><div><code>pending</code><span>Remboursement attendu du commerçant</span></div><div><code>proof_submitted</code><span>Référence et preuve transmises</span></div><div class="refund-verified"><code>verified</code><span>Vérification positive par Delifast</span></div><div class="refund-rejected"><code>rejected</code><span>Rejet obligatoirement motivé et transmis au commerçant. L’annulation reste <code>cancellation_pending</code> ; le client la voit en attente. Le commerçant peut renvoyer sans limite ni expiration ; l’administrateur revérifie.</span></div></div></div><div class="scope-grid"><div class="scope-card"><strong>Après vérification positive · totale</strong><span>La commande peut être finalisée avec le statut <code>cancelled</code>, sans reprise de préparation.</span></div><div class="scope-card"><strong>Après vérification positive · partielle</strong><span>L’annulation est finalisée. Le commerçant confirme la reprise des articles restants ; la commande reste <code>partially_cancelled</code> tant qu’il reste des articles actifs, puis <code>completed</code> après leur remise.</span></div></div>${merchantControls}${refundAction}${correctedProof}${verifyAction}${proofHistory}<p class="footer-note">Les notifications, preuves, vérifications, confirmations et remboursements illustrés sont fictifs ; cette maquette n’envoie aucun message et ne déclenche aucune opération réelle.</p></article>`;
}

function renderOrderDetail(s) {
  const isClient=s.id===16, isMerchant=s.id===33, isAdmin=s.id===47;
  const role=isClient?'Client':isMerchant?'Commerçant':'Administration';
  const status=isAdmin?'cancellation_pending · annulation en cours':'preparing · préparation commencée';
  const paymentFacts=isClient?`<div class="detail-pair"><small>Montant du paiement</small><strong>9 500 FCFA · fictif</strong></div><div class="detail-pair"><small>Bénéficiaire</small><strong>Restaurant Démo · fictif</strong></div><div class="detail-pair"><small>Opérateur</small><strong>Orange Money · démo</strong></div><div class="detail-pair"><small>Statut du paiement</small><strong>Validé · exemple fictif</strong></div><div class="detail-pair"><small>Référence de paiement</small><strong>PAY-DEMO-0001 · fictif</strong></div>`:'';
  const reserved=renderReservationCard(role);
  const proposal=isClient||isMerchant?renderChangeProposal(role):`<article class="panel"><div class="panel-title"><h2>Historique de la modification</h2><span class="subtle">Étapes successives</span></div><div class="proposal-choices"><div class="proposal-choice"><strong>Composition conservée</strong><span>Accompagnement · Frites × 1</span><small>Ancien montant · 10 000 FCFA</small></div><div class="proposal-choice"><strong>Nouvelle composition proposée</strong><span>Remplacement par Riz × 1</span><small>Nouveau montant · 9 500 FCFA</small></div></div><div class="timeline"><div class="timeline-item"><span class="timeline-dot">·</span><div><strong>pending_customer_approval → rejected</strong><small>Refus explicite du client ; choix total ou partiel enregistré dans la demande d’annulation.</small></div></div></div></article>`;
  const cancellation=renderCancellationWorkflow(role);
  const sideNote=isAdmin
    ? `L’administration vérifie la référence et la preuve. Tout rejet doit comporter un motif transmis au commerçant ; chaque dépôt et décision reste dans l’historique append-only.`
    : isMerchant
      ? `Le commerçant rembourse directement. Après rejet, il peut corriger et renvoyer la preuve sans limite arbitraire ni expiration ; l’administrateur la vérifie. Aucune opération réelle n’est exécutée par cette maquette.`
      : `En cas de rejet, l’annulation reste en attente de régularisation. Attendez la preuve corrigée et sa vérification ; l’aperçu n’envoie aucun message réel.`;
  return `<div class="detail-grid"><div class="stack"><article class="panel"><div class="panel-title"><h2>Commande #DF-24018</h2>${badge(status,'pill-warn')}</div><div class="detail-list"><div class="detail-pair"><small>Commerce unique</small><strong>Saveurs du Faso</strong></div><div class="detail-pair"><small>Client</small><strong>Client Démo</strong></div><div class="detail-pair"><small>Date</small><strong>06 nov. 2026 · exemple</strong></div>${paymentFacts}<div class="detail-pair"><small>Préparation</small><strong>${isAdmin?'Commencée · arrêt à confirmer par le commerçant':'Commencée · exemple'}</strong></div></div></article><article class="panel"><div class="panel-title"><h2>Articles et composition historique</h2><span class="pill pill-success">Snapshot conservé</span></div><div class="order-line workflow-line"><div class="order-left"><strong>Poulet braisé × 2</strong><small>Prix de base : 3 000 FCFA par unité</small><small>Option · supplément : 500 FCFA par unité</small><small>Remise de ligne : 1 000 FCFA au total · 500 par unité</small><small>Remise globale allouée : 600 FCFA · 300 par unité</small><span class="line-scope">Prix net historique : 2 700 FCFA par unité · une unité ciblée</span></div><strong>5 400 FCFA</strong></div><div class="order-line workflow-line"><div class="order-left"><strong>Menu du jour × 1</strong><small>Prix historique : 4 000 FCFA</small><small>Remise globale allouée : 400 FCFA</small><span class="line-scope line-remaining">Prix net historique : 3 600 FCFA · article restant</span></div><strong>3 600 FCFA</strong></div><div class="footer-note">Remise globale totale : 1 000 FCFA, répartie au prorata des montants après ajustements propres aux articles (6 000 / 4 000), puis figée dans le snapshot.</div></article>${proposal}${cancellation}${reserved}<article class="panel"><div class="panel-title"><h2>Historique de commande</h2><span class="subtle">Démonstration · aucun message réel</span></div><div class="timeline"><div class="timeline-item"><span class="timeline-dot">✓</span><div><strong>Commande envoyée · réservation créée</strong><small>06 nov. 2026 · exemple</small></div></div><div class="timeline-item"><span class="timeline-dot">·</span><div><strong>Proposition de retrait ou remplacement soumise à l’accord explicite du client.</strong><small>Ancienne et nouvelle composition et montants conservés.</small></div></div><div class="timeline-item"><span class="timeline-dot">·</span><div><strong>Après refus, le client choisit le périmètre ; la préparation commencée est arrêtée sur confirmation du commerçant.</strong><small>Une annulation partielle finalisée est suivie de la confirmation de reprise des articles restants.</small></div></div></div></article></div><aside class="stack"><article class="panel"><div class="panel-title"><h3>Résumé</h3></div><div class="summary-line"><span>Articles après remises</span><strong>9 000 FCFA</strong></div><div class="summary-line"><span>Frais partagés · livraison exemple</span><strong>1 000 FCFA</strong></div><div class="summary-total"><span>Total effectivement payé · exemple</span><span>10 000 FCFA</span></div><p class="footer-note">Annulation totale : remboursement de 10 000 FCFA, frais compris. Annulation partielle d’une unité : (3 000 + 500 − 500 − 300) × 1 = 2 700 FCFA ; les frais partagés de 1 000 FCFA restent inchangés.</p><p class="footer-note">Toutes les informations sont fictives.</p></article><article class="side-help"><h3>Contrôle du remboursement</h3><p>${sideNote}</p></article></aside></div>`;
}

function renderPaymentReview(s) {
  const isSubscription=s.id===49;
  const isAdminDetail=s.id===51;
  const isMerchant=s.id===35;
  const heading=isSubscription?'Abonnement SUB-DEMO-0001':'Paiement PAY-DEMO-0001';
  const detailRows=isSubscription
    ? [['Type','Abonnement restaurant · fictif'],['Commerçant','Commerçant Démo · fictif'],['Restaurant','Restaurant Démo · fictif'],['Formule','Découverte · exemple fictif'],['Montant attendu','3 000 F CFA / mois · Découverte'],['Opérateur','Orange Money · démo fictive'],['Numéro bénéficiaire Delifast','+226 XX XX XX XX · fictif'],['Référence de transaction','TXN-DEMO-0002 · fictif'],['Date de soumission','Date fictive'],['Statut','En attente']]
    : isAdminDetail
      ? [['Type','Paiement de commande · fictif'],['Restaurant bénéficiaire','Restaurant Démo · fictif'],['Commerçant concerné','Commerçant Démo · fictif'],['Commande ou abonnement associé','CMD-DEMO-0001 · commande fictive'],['Client','Client Démo · fictif'],['Montant attendu','9 500 FCFA · FICTIF'],['Opérateur','Orange Money · démo fictive'],['Numéro bénéficiaire historique','+226 70 XX XX XX XX · fictif'],['Référence de transaction','TXN-DEMO-0002 · fictif'],['Date de soumission','Date fictive'],['Statut','En attente']]
      : [['Type','Paiement de commande · fictif'],['Commande','CMD-DEMO-0001 · fictif'],['Client','Client Démo · fictif'],['Restaurant bénéficiaire','Restaurant Démo · fictif'],['Montant attendu','9 500 FCFA · FICTIF'],['Opérateur','Orange Money · démo fictive'],['Numéro bénéficiaire historique','+226 70 XX XX XX XX · fictif'],['Référence de transaction','TXN-DEMO-0002 · fictif'],['Date de soumission','Date fictive'],['Statut','En attente']];
  const history=`<article class="panel"><div class="panel-title"><h2>Historique des soumissions</h2><span class="subtle">Append-only · données fictives</span></div><div class="proof-history"><div class="proof-history-row"><strong>Soumission 1 · Refusé · fictif</strong><span>PAY-DEMO-0001 · TXN-DEMO-0001</span><small>Motif obligatoire · exemple fictif : référence non rapprochée. Vérificateur · ${isSubscription?'Administrateur Démo':'Restaurant bénéficiaire · démo'}.</small><small>Capture : PREUVE-DEMO-0001 · date de soumission et vérification fictives.</small></div><div class="proof-history-row"><strong>Soumission 2 · En attente · fictif</strong><span>TXN-DEMO-0002 · nouvelle preuve distincte</span><small>Chemin fictif : PREUVE-DEMO-0002 · vérificateur et date de décision à renseigner.</small></div></div><div class="detail-list payment-history-fields"><div class="detail-pair"><small>Identifiant du paiement</small><strong>PAY-DEMO-0001 · fictif</strong></div><div class="detail-pair"><small>Numéro de soumission</small><strong>2 · exemple fictif</strong></div><div class="detail-pair"><small>Chemin du fichier</small><strong>PREUVE-DEMO-0002 · fictif</strong></div></div></article>`;
  const decision=isAdminDetail
    ? `<article class="panel"><div class="panel-title"><h3>Accès d’administration · supervision</h3></div><p>Pour un paiement de commande, l’administration consulte sans remplacer la décision du restaurant. Pour un abonnement destiné à Delifast, la décision administrative se prend à l’écran 49.</p><div class="payment-actions"><a class="btn btn-outline btn-small" href="?ecran=47">Voir la commande · aperçu</a><a class="btn btn-outline btn-small" href="?ecran=49">Voir l’abonnement · aperçu</a><a class="btn btn-outline btn-small" href="?ecran=43">Voir le commerçant · aperçu</a><a class="btn btn-outline btn-small" href="?ecran=50">Retour à la liste · aperçu</a></div><div class="payment-state-grid"><span>En attente</span><span>Validé</span><span>Refusé · motif obligatoire</span><span>Justificatif manquant</span></div><p class="footer-note">Liens de navigation uniquement; aucune décision, notification ou opération réelle.</p></article>`
    : `<article class="panel"><div class="panel-title"><h3>${isSubscription?'Décision réservée à l’administration':'Décision réservée au bénéficiaire'}</h3><span class="pill pill-warn">Motif requis en cas de refus</span></div><label class="field-label-demo">Motif obligatoire si refus</label><textarea class="demo-textarea" disabled placeholder="Exemple fictif — aucun motif n’est enregistré"></textarea><div class="payment-actions"><button class="btn btn-primary" type="button" disabled>Valider après vérification</button><button class="btn btn-outline" type="button" disabled>Refuser avec un motif</button>${isMerchant?'<a class="btn btn-outline btn-small" href="?ecran=33">Consulter la commande · aperçu</a>':isSubscription?'<a class="btn btn-outline btn-small" href="?ecran=48">Retour aux abonnements · aperçu</a>':''}</div><p class="footer-note">${isSubscription?'Décision réservée à l’administrateur; seule la validation active ou réactive l’abonnement. Une suspension administrative indépendante demeure en vigueur.':'Décision réservée au restaurant bénéficiaire. Le client serait notifié, avec le motif en cas de refus.'} Aucune action ni notification réelle.</p></article>`;
  const stockInfo=isMerchant?`<article class="panel reservation-payment-note"><div class="panel-title"><h3>Effet sur la réservation · règle métier conservée</h3><span class="pill pill-warn">Exemple fictif</span></div><p>Une validation manuelle consomme le stock réservé; un refus le libère avant consommation. Cette maquette ne modifie aucun stock.</p></article>`:'';
  return `<div class="payment-demo-banner"><strong>Vérification manuelle · aperçu fictif</strong><span>La preuve se compare au SMS réellement reçu; aucune capture réelle n’est présentée.</span></div><div class="detail-grid payment-review-layout"><div class="stack"><article class="panel"><div class="panel-title"><h2>${heading}</h2>${badge('En attente','pill-warn')}</div><div class="detail-list">${detailRows.map(([label,value])=>`<div class="detail-pair"><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`).join('')}</div></article><article class="panel"><div class="panel-title"><h2>Capture du SMS de confirmation</h2><span class="subtle">Fichier privé · démonstration</span></div><div class="proof-placeholder proof-preview"><span aria-hidden="true">▧</span><div><strong>Capture fictive · non consultable</strong><small>PREUVE-DEMO-0002 · aucun fichier réel</small></div></div><button class="btn btn-outline btn-small" type="button" disabled>Agrandir la capture · désactivé</button><p class="footer-note">Le bénéficiaire compare la référence et les détails au SMS réellement reçu sur son numéro Mobile Money.</p></article>${history}</div><aside class="stack"><article class="side-help"><h3>Vérifier le bon circuit</h3><p>${isSubscription?'Le bénéficiaire est Delifast. Seul l’administrateur compare la preuve au SMS reçu sur le numéro Delifast et décide. Découverte coûte 3 000 F CFA par mois et Professionnel 4 500 F CFA par mois. Chaque nouveau compte marchand bénéficie d’un premier mois gratuit, accordé une seule fois par compte marchand, puis le renouvellement est payant. Après expiration d’un abonnement payant, la grâce dure 72 heures; sans renouvellement validé, le compte est suspendu.':'Le bénéficiaire est le restaurant choisi. Seul ce restaurant compare la preuve au SMS reçu sur son numéro et décide.'} Aucun autre rôle ne peut se substituer au bénéficiaire.</p></article>${decision}${stockInfo}</aside></div>`;
}
  function renderSubscription() {
    return renderMerchantSubscription();
  }

  function renderSubscriptionPayment() {
    const operatorCard=(name,mark,phone,code)=>`<article class="payment-method payment-method-card"><span class="method-mark">${mark}</span><div class="payment-method-copy"><strong>${name} · bénéficiaire Delifast</strong><small>Numéro fictif · ${phone} · non fonctionnel</small><code class="ussd-example">${code}</code><small class="demo-code-note">Code d’illustration uniquement · NON APPELABLE</small><div class="payment-actions"><button class="btn btn-primary btn-small" type="button" disabled>Ouvrir le code de paiement</button><button class="btn btn-outline btn-small" type="button" disabled>Copier le numéro</button></div></div><span class="pill pill-success">Disponible · démo fictive</span></article>`;
    return `<div class="payment-demo-banner"><strong>Abonnement à Delifast · démonstration fictive</strong><span>Aucun composeur, paiement, abonnement ou téléversement n’est activé.</span></div><div class="checkout-columns payment-demo-layout"><section class="stack"><article class="panel"><div class="panel-title"><h2>Forfait Découverte · exemple</h2>${badge('Non soumis','pill-warn')}</div><div class="detail-list"><div class="detail-pair"><small>Montant mensuel du forfait</small><strong>3 000 F CFA / mois</strong></div><div class="detail-pair"><small>Durée</small><strong>Un mois · exemple fictif</strong></div><div class="detail-pair"><small>Bénéficiaire</small><strong>Delifast · numéro fictif</strong></div></div><p class="subtle">Chaque nouveau compte marchand bénéficie d’un premier mois gratuit, accordé une seule fois par compte marchand; après ce mois, le renouvellement est payant. Le montant vient du forfait et n’est pas modifiable par le restaurant.</p><div class="payment-operator-list">${operatorCard('Orange Money','O','NUMERO_FICTIF_ORANGE','*144*2*1*NUMERO_FICTIF*MONTANT_FICTIF#')}${operatorCard('Telmob','T','NUMERO_FICTIF_TELMOB','*555*2*1*NUMERO_FICTIF*MONTANT_FICTIF#')}</div><div class="payment-instructions"><h3>Parcours prévu</h3><ol><li>Choisir un opérateur configuré et consulter le code.</li><li>Effectuer et confirmer la transaction sur le téléphone.</li><li>Revenir dans Delifast, puis transmettre la capture du SMS et la référence.</li><li>Attendre la comparaison et la décision de l’administrateur.</li></ol></div><div class="banner-notice"><span class="notice-icon">i</span><span>À l’expiration d’un abonnement payant, 72 heures de grâce sont prévues : pendant ce délai le compte reste opérationnel et reçoit des rappels. Après suspension, seule la validation du paiement réactive l’abonnement.</span></div></article></section><aside class="stack"><article class="panel"><div class="panel-title"><h2>Référence et preuve · après paiement</h2></div><div class="field-grid"><div class="field full"><label>Référence de transaction · obligatoire</label><input disabled placeholder="TXN-DEMO-0001 · fictif"></div><div class="field full"><label>Capture du SMS · obligatoire</label><button class="btn btn-outline demo-disabled-control" type="button" disabled>Sélectionner une image · désactivé</button><small class="field-hint">Prévisualiser, retirer ou remplacer seraient des actions de maquette; aucun fichier n’est lu ou envoyé.</small></div></div><div class="proof-placeholder"><span aria-hidden="true">▧</span><div><strong>Aucun aperçu réel</strong><small>Référence, numéro et code d’exemple fictifs.</small></div></div><div class="payment-actions"><button class="btn btn-outline btn-small" type="button" disabled>Prévisualiser</button><button class="btn btn-outline btn-small" type="button" disabled>Retirer</button><button class="btn btn-outline btn-small" type="button" disabled>Remplacer</button></div><div class="banner-notice"><span class="notice-icon">i</span><span>La preuve est adressée à l’administration. L’abonnement reste inactif jusqu’à la validation de l’administrateur; un refus doit comporter un motif.</span></div><button class="btn btn-primary demo-disabled-control" type="button" disabled>Envoyer la preuve</button></article></aside></div>`;
  }

